(function () {
  var d = Object.getOwnPropertyDescriptor(Node.prototype, "textContent");
  Object.defineProperty(Node.prototype, "textContent", {
    configurable: true,
    get: d.get,
    set: function (v) {
      var t = String(v);
      if (this.nodeType === 1) {
        var c = this.firstChild;
        if (c && c.nodeType === 3 && !c.nextSibling && c.data === t) return;
        if (!c && t === "") return;
