    if (!down || held || scrolling) return;
    if (!moved) {
      var dx = Math.abs(e.clientX - sx),
        dy = Math.abs(e.clientY - sy);
      if (dy > 8 && dy >= dx) {
        scrolling = true;
        clearTimeout(timer);
        return;
      }
      if (dx > 10 && dx > 1.8 * dy) {
        moved = true;
        clearTimeout(timer);
      }
    }
