function onHold(el, fn) {
  var timer = 0,
    sx = 0,
    sy = 0,
    fired = false;
  function stop() {
    clearTimeout(timer);
    timer = 0;
  }
  el.addEventListener("pointerdown", function (e) {
    if (e.button) return;
    fired = false;
    sx = e.clientX;
    sy = e.clientY;
    stop();
    timer = setTimeout(function () {
      timer = 0;
      if (editing()) return;
      fired = true;
      fn();
    }, 450);
  });
  el.addEventListener("pointermove", function (e) {
    if (timer && (Math.abs(e.clientX - sx) > 8 || Math.abs(e.clientY - sy) > 8)) stop();
  });
  ["pointerup", "pointercancel", "pointerleave"].forEach(function (ev) {
    el.addEventListener(ev, stop);
  });
  return function () {
    var was = fired;
    fired = false;
    return was;
  };
}

/* A locked lock unlocks by sliding its icon across its row, as on the old iPhone lock screen: drag the icon to the end; letting go
   before the end sends it back. A tap only nudges the icon to show which way to go. o.canSlide() says whether the slide applies now. */
function slideIcon(r, o, refresh) {
  var icn = r.querySelector(".ic"),
    fade = r.querySelectorAll(".tx,.vl"),
    from = 0,
    x = 0,
    drag = false,
    moved = false,
    reset = 0;
  function room() {
    return r.clientWidth - icn.offsetWidth - 16;
  }
  function place(v) {
    x = v;
    icn.style.transform = v ? "translateX(" + v + "px)" : "";
    var f = String(Math.max(0, 1 - v / (room() * 0.5)));
    for (var i = 0; i < fade.length; i++) fade[i].style.opacity = v ? f : "";
  }
  function back() {
    r.classList.add("easing");
    place(0);
  }
  r.slideReset = function () {
    clearTimeout(reset);
    if (x) back();
  };
  icn.addEventListener("pointerdown", function (e) {
    if (e.button || editing() || !o.canSlide()) return;
    clearTimeout(reset);
    r.classList.remove("easing");
    r.classList.add("sliding");
    from = e.clientX - x;
    drag = true;
    moved = false;
    capturePointer(icn, e);
  });
  icn.addEventListener("pointermove", function (e) {
    if (!drag) return;
    var v = Math.max(0, Math.min(room(), e.clientX - from));
    if (v > 6) moved = true;
    place(v);
  });
  function release() {
    if (!drag) return;
    drag = false;
    r.classList.remove("sliding");
    if (moved && x >= room() * 0.9) {
      o.slide();
      reset = setTimeout(back, 5000);
    } else back();
  }
  icn.addEventListener("pointerup", release);
  icn.addEventListener("pointercancel", release);
  icn.addEventListener(
    "click",
    function (e) {
      if (!o.canSlide() || editing()) return;
      e.stopPropagation();
      if (moved) return;
      r.classList.add("easing");
      place(18);
      setTimeout(back, 180);
    },
    true
  );
}

/* The kind of device an icon stands for. A row's colour comes from its kind: lights amber, climate and air blue, media violet, security green, power and batteries lime, cleaning teal, scenes and actions pink, appliances and blinds their own warm and sage tones, warnings orange, links slate. Any other icon is "other", which takes the dashboard accent, so no icon is left without a colour. */
var KINDWORDS = [
  ["power", /^(plug|powerset|power|battery)/, ["power", "battery", "flash", "lightning", "bolt", "solar", "meter", "current", "ev", "outlet", "socket", "transmission", "gauge"]],
  ["light", /^(light|lamp|floor|ceiling|strip|bright|flood|lights)/, ["lamp", "light", "lightbulb", "bulb", "led", "sconce", "chandelier", "ceiling", "spotlight", "candle", "lantern", "torch"]],
  ["climate", /^(ac|fan|purifier|thermo|drop)/, ["air", "fan", "snowflake", "thermometer", "thermostat", "radiator", "heat", "water", "humidity", "weather", "wind", "temperature", "fire", "fireplace"]],
  ["media", /^(tv|apple|speaker|media|movie|playc)/, ["television", "speaker", "music", "cast", "projector", "youtube", "netflix", "radio", "disc", "amplifier", "surround", "apple", "android", "monitor", "remote", "headphones", "audio", "soundbar"]],
  ["security", /^(lock|padlock|cam|cctv|camoff|walk|motion|bell|phone)/, ["lock", "door", "shield", "cctv", "camera", "doorbell", "garage", "alarm", "smoke", "phone", "bell", "gate", "key", "window", "intercom", "motion", "walk", "run"]],
  ["clean", /^(vac|broom|rug)/, ["robot", "vacuum", "broom", "mop", "spray", "roomba", "sweep"]],
  ["scene", /^(scene|sparkle|palette|play|rec)/, ["palette", "party", "creation", "auto", "star", "heart", "play", "script", "movie", "theater", "sunset", "sunrise", "weather-night"]],
  ["appliance", /^(printer)/, ["printer", "stove", "fridge", "refrigerator", "coffee", "kettle", "microwave", "dishwasher", "oven", "toaster", "blender", "iron", "hair", "washing", "dryer", "cooker", "boiler", "washer"]],
  ["cover", /^(blind|shutter)/, ["blinds", "shutter", "roller", "curtains", "curtain"]],
  ["alert", /^(alert|warn)/, ["alert", "warning"]],
  ["link", /^(swap|link)/, ["link", "share", "swap"]],
];

/* A Material Design name is read word by word (mdi:desk-lamp is a lamp), the built-in names by how they begin. */
function iconKind(icon) {
  var n = String(icon || "");
  if (!n) return "";
  var words = n.indexOf("mdi:") === 0 ? n.slice(4).split("-") : null;
  for (var i = 0; i < KINDWORDS.length; i++) {
    var k = KINDWORDS[i];
    if (!words && k[1].test(n)) return k[0];
    if (
      words &&
      words.some(function (w) {
        return k[2].indexOf(w) >= 0;
      })
    )
      return k[0];
  }
  return "other";
}

/* A small round button at the end of a row (play and pause on a media row): its own tap, never the row's. */
function rowAction(r, o) {
  var b = mk("button", "pact", svg(o.icon()));
  b.setAttribute("aria-label", o.label);
  b.type = "button";
  b.addEventListener("click", function (e) {
    e.stopPropagation();
    o.fn();
  });
  r.appendChild(b);
  return b;
}

/* The picture of a row, when it has one (the artwork of what is playing), in place of the icon. */
function rowArt(icn, url, icon) {
  var ok = typeof url === "string" && /^(\/(?!\/)|https:\/\/)/.test(url);
  if (icn._art === (ok ? url : "")) return;
  icn._art = ok ? url : "";
  icn.classList.toggle("art", ok);
  icn.innerHTML = svg(icon);
  if (!ok) return;
  var im = new Image();
  im.alt = "";
  im.onload = function () {
    if (icn._art === url) icn.innerHTML = "";
    if (icn._art === url) icn.appendChild(im);
  };
  im.src = url;
}

function pill(icon, name, o) {
  var r = mk("div", "pill pane" + (o.tap ? "" : " static") + (o.on ? " tg" : ""));
  r.dataset.i = icon;
  var kind = o.kind || iconKind(icon);
  if (kind) r.dataset.k = kind;
  r.innerHTML =
    ic(icon) +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='vl'></span>";
  r.querySelector(".nm").textContent = name;
  var sb = r.querySelector(".sb"),
    vl = r.querySelector(".vl"),
    act = o.action ? rowAction(r, o.action) : null;
  if (o.pin) r.dataset.pin = JSON.stringify(o.pin);
  if (o.check) {
    r.classList.add("chk");
    r.setAttribute("role", "checkbox");
    r.appendChild(mk("span", "ck", svg("check")));
  }
  /* A row with an icon action opens its popup on a press and hold as well; the icon switches the device only on a tap. */
  var held = o.iconTap && o.tap ? onHold(r, o.tap) : null;
  if (o.tap)
    r.addEventListener("click", function (e) {
      if (held && held()) return;
      if (o.iconTap && e.target.closest(".ic")) {
        o.iconTap();
        return;
      }
      o.tap();
    });
  if (o.slide) slideIcon(r, o);
  var was = null;
  r.refresh = function () {
    if (o.slide) {
      var can = !!o.canSlide();
      r.classList.toggle("slidable", can);
      if (!can && r.slideReset) r.slideReset();
    }
    if (o.check) {
      var ck = !!o.check();
      r.classList.toggle("checked", ck);
      r.setAttribute("aria-checked", ck ? "true" : "false");
    }
    var n = o.on ? !!o.on() : false;
    r.classList.toggle("on", n);
    if (was !== null && n !== was) pop(r);
    was = n;
    var tone = o.tone ? o.tone() : kind;
    if (tone) r.dataset.k = tone;
    else delete r.dataset.k;
    if (o.art) rowArt(r.querySelector(".ic"), o.art(), icon);
    if (act) {
      var show = !!o.action.show();
      act.style.display = show ? "" : "none";
      var ai = show ? o.action.icon() : "";
      if (show && ai !== act._i) {
        act._i = ai;
        act.innerHTML = svg(ai);
      }
    }
    if (o.sub) {
      var t = o.sub();
      sb.textContent = t || "";
      sb.style.display = t ? "" : "none";
    } else sb.style.display = "none";
    vl.textContent = r.classList.contains("slidable") ? _T("slide_to_unlock") : o.val ? o.val() : "";
  };
  reg(r.refresh);
  return r;
}

/* A CSS colour string as [r,g,b], so text can be chosen against it. */
function cssToRgb(s) {
  var e = document.createElement("span");
  e.style.color = s;
  e.style.display = "none";
  document.body.appendChild(e);
  var m = (getComputedStyle(e).color.match(/[\d.]+/g) || []).slice(0, 3).map(Number);
  e.remove();
  return m.length === 3 ? m : null;
}

function sliderRow(o) {
  var r = mk("div", "pill pane slide");
  if (iconKind(o.icon)) r.dataset.k = iconKind(o.icon);
  r.innerHTML =
    "<div class='fill'></div>" +
    ic(o.icon) +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='vl'></span>";
  r.querySelector(".nm").textContent = o.name;
  var fill = r.querySelector(".fill"),
    sb = r.querySelector(".sb"),
    vl = r.querySelector(".vl");
  var drag = false;
  /* While dragging, the thing the slider controls follows the finger: at most one update every 150 ms, and the last position always arrives. */
  var liveT = 0,
    liveAt = 0;
  function sendLive(v) {
    var wait = liveAt + 150 - Date.now();
    clearTimeout(liveT);
    if (wait <= 0) {
      liveAt = Date.now();
      o.live(v);
    } else
      liveT = setTimeout(function () {
        liveAt = Date.now();
        o.live(v);
      }, wait);
  }
  function snap(f) {
    var v = o.min + f * (o.max - o.min);
    var st = o.step || 1;
    v = Math.round((v - o.min) / st) * st + o.min;
    return Math.max(o.min, Math.min(o.max, Number(v.toFixed(2))));
  }
  function paint(v) {
    var f = (v - o.min) / (o.max - o.min);
    f = Math.max(0, Math.min(1, f));
    fill.style.width = f * 100 + "%";
    vl.textContent = o.fmt ? o.fmt(v) : v;
    if (o.fillColor) {
      var fc2 = o.fillColor();
      inkRow(r, fc2 ? cssToRgb(fc2) : null, f * 100);
    }
  }
  if (!o.readonly)
    attachSlide(r, {
      onMove: function (f) {
        drag = true;
        var v = snap(f);
        paint(v);
        if (o.live) sendLive(v);
      },
      onCommit: function (f) {
        var v = snap(f);
        clearTimeout(liveT);
        o.commit(v);
        setTimeout(function () {
          drag = false;
        }, 600);
      },
      onCancel: function () {
        drag = false;
      },
      onHold: o.onHold,
      onTap: function (t) {
        drag = false;
        if (o.onTap) o.onTap(t);
      },
    });
  else r.classList.add("static");
  r.refresh = function () {
    if (o.inert) r.classList.toggle("inert", !!o.inert());
    if (o.fillColor) {
      var fc = o.fillColor();
      if (fc) {
        fill.style.background =
          "linear-gradient(180deg," + fc + ",color-mix(in srgb," + fc + " 75%,#000))";
        fill.style.boxShadow = "inset 0 1.5px 1px rgba(255,255,255,.6),0 0 24px " + fc;
      } else {
        fill.style.background = "";
        fill.style.boxShadow = "";
      }
    }
    if (o.on) r.classList.toggle("on", !!o.on());
    if (o.sub) {
      var t = o.sub();
      sb.textContent = t || "";
      sb.style.display = t ? "" : "none";
    } else sb.style.display = "none";
    if (drag) return;
    var v = o.get();
    if (v === null || v === undefined || isNaN(Number(v))) {
      if (o.off !== undefined) {
        fill.style.width = "0";
        vl.textContent = o.off;
      }
      return;
    }
    paint(Number(v));
  };
  reg(r.refresh);
  return r;
}

function selectTile(label, opts, cur, pick, icon, fmt) {
  var r = mk("div", "sel pane");
  if (iconKind(icon)) r.dataset.k = iconKind(icon);
  r.innerHTML =
    (icon ? ic(icon) : "") +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='chev'>" +
    svg("chev") +
    "</span>";
  r.querySelector(".nm").textContent = label;
  var sb = r.querySelector(".sb");
  r.addEventListener("click", function () {
    var o = opts();
    if (!o || !o.length) return;
    pop(r);
    openMenu(r, o, cur(), pick, fmt);
  });
  r.refresh = function () {
    var c = cur();
    sb.textContent = c === undefined || c === null || c === "" ? "-" : fmt ? fmt(c) : cap(c);
  };
  reg(r.refresh);
  return r;
}

/* A dropdown that can have several choices ticked: it stays open while ticking. `opts()` gives [value, label] pairs, `isOn(value)` says whether one is ticked, `toggle(value)` flips it, and `summary()` is the line under its name. */
function multiTile(label, opts, isOn, toggle, icon, summary, state) {
  var r = mk("div", "sel selrow pane");
  r.innerHTML =
    (icon ? ic(icon) : "") +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='chev'>" +
    svg("chev") +
    "</span>";
  r.querySelector(".nm").textContent = label;
  var sb = r.querySelector(".sb");
  r.addEventListener("click", function () {
    var o = opts();
    if (!o || !o.length) return;
    pop(r);
    openMenu(r, o.map(function (x) { return x[0]; }), null, function () {}, function (v) {
      return (o.filter(function (x) { return x[0] === v; })[0] || [v, v])[1];
    }, { on: isOn, state: state, toggle: function (v) { toggle(v); r.refresh(); } });
  });
  r.refresh = function () {
    sb.textContent = summary();
  };
  reg(r.refresh);
  r.refresh();
  return r;
}

var MENU_ANCHOR = null;

/* The classes of a tick-several choice: " on" ticked, " ex" left out (when it has a third state). */
function multiClass(multi, o) {
  if (multi.state) return multi.state(o) === 1 ? " on" : multi.state(o) === 2 ? " ex" : "";
  return multi.on(o) ? " on" : "";
}

function openMenu(anchor, options, current, pick, fmt, multi) {
  closeMenu(true);
  var m = mk("div", "menu pane" + (multi ? " multi" : ""));
  options.forEach(function (o) {
    var it = mk("div", "mi" + (multi ? multiClass(multi, o) : String(o) === String(current) ? " on" : ""));
    if (multi) {
      var tx = mk("span", "mt");
      tx.textContent = fmt ? fmt(o) : cap(o);
      it.appendChild(tx);
      it.appendChild(mk("span", "ck", svg("check")));
      it.appendChild(mk("span", "xk", svg("close")));
    } else it.textContent = fmt ? fmt(o) : cap(o); /* an option comes from a device and is text, never markup */
    it.addEventListener("click", function (e) {
      e.stopPropagation();
      if (multi) {
        multi.toggle(o);
        m.querySelectorAll(".mi").forEach(function (el, i) {
          el.className = "mi" + multiClass(multi, options[i]);
        });
        return;
      }
      closeMenu();
      pick(o);
    });
    m.appendChild(it);
  });
  placeMenu(m, anchor);
}

/* A floating layer over the page, opened from `anchor`: as wide as it, starting at its edge, below it or above when there is no room. A tap away closes it. */
function placeMenu(m, anchor) {
  document.body.appendChild(m);
  /* The menu is as wide as the button it opens from and starts at its edge, measured at full size even when the button is shrunk by a press. */
  var r = anchor.getBoundingClientRect(),
    aw = anchor.offsetWidth,
    ax = r.left + (r.width - aw) / 2;
  m.style.width = aw + "px";
  var mh = m.offsetHeight,
    left = Math.max(8, Math.min(window.innerWidth - m.offsetWidth - 8, ax)),
    top = r.bottom + 6,
    up = false;
  if (top + mh > window.innerHeight - 8) {
    top = Math.max(8, r.top - mh - 6);
    up = true;
  }
  m.style.left = left + "px";
  m.style.top = top + "px";
  if (up) m.classList.add("up");
  m.style.setProperty(
    "--ox",
    Math.max(0, Math.min(100, ((ax + aw / 2 - left) / Math.max(1, m.offsetWidth)) * 100)) +
      "%"
  );
  anchor.classList.add("open");
  MENU_ANCHOR = anchor;
  MENU = m;
  setTimeout(function () {
    document.addEventListener("pointerdown", menuAway, true);
  }, 0);
}

/* A tap away from a menu closes it. A tap on what opened it (a dropdown, a popup's title, the now playing row) only closes it: the click that follows is taken, so that it does
   not open it again. */
function menuAway(e) {
  if (!MENU || MENU.contains(e.target)) return;
  if (MENU_ANCHOR && MENU_ANCHOR.contains(e.target)) menuEatClick(MENU_ANCHOR);
  closeMenu();
}

function menuEatClick(anchor) {
  var timer = 0;
  function done() {
    clearTimeout(timer);
    document.removeEventListener("click", eat, true);
  }
  function eat(e) {
    if (!anchor.contains(e.target)) return;
    e.stopPropagation();
    e.preventDefault();
    done();
  }
  document.addEventListener("click", eat, true);
  /* a press that ends elsewhere has no click to take */
  timer = setTimeout(done, 2500);
}

function closeMenu(instant) {
  document.removeEventListener("pointerdown", menuAway, true);
  if (MENU_ANCHOR) {
    MENU_ANCHOR.classList.remove("open");
    MENU_ANCHOR = null;
  }
  if (MENU) {
    var m = MENU;
    MENU = null;
    if (instant) m.remove();
    else {
      m.classList.add("out");
      setTimeout(function () {
        if (m !== MENU) m.remove();
      }, 170);
    }
  }
}

/* A small grey line of explanation in a popup, under the row or choice it explains. */
function hintRow(text) {
  var h = mk("div", "hint");
  h.textContent = text;
  return h;
}

/* A row that switches one yes/no setting of an object, kept as a flag that is there when it is on (and removed when it is off, so saved settings stay small). `sub(on)` words the state;
   `inverted` is for a flag that names the exception (noslide: "no slider"), where the row is on while the flag is absent. Every change is saved at once. */
/* The one way every object says whether it is shown: a row "Visible", On or Off. `isOn()` says whether it is shown now and `toggle()` flips it. */
/* One named part of something, shown or hidden. */
function partPill(title, isOn, toggle) {
  return pill("eye", title, {
    on: isOn,
    sub: function () {
      return isOn() ? _T("on_cap") : _T("off");
    },
    tap: toggle,
  });
}

function visiblePill(isOn, toggle) {
  return pill("eye", _T("visible"), {
    on: isOn,
    sub: function () {
      return isOn() ? _T("on_cap") : _T("off");
    },
    tap: toggle,
  });
}

function flagPill(icon, title, obj, key, sub, inverted) {
  function on() {
    return inverted ? !obj[key] : !!obj[key];
  }
  return pill(icon, title, {
    on: on,
    sub: function () {
      return sub(on());
    },
    tap: function () {
      if (obj[key]) delete obj[key];
      else obj[key] = 1;
      uiChanged();
    },
  });
}

/* A short explanation and the segmented choice it explains, added to `parent`. */
function segField(parent, label, options, current, pick) {
  parent.appendChild(hintRow(label));
  parent.appendChild(seg(options, current, pick));
}

function sep(name, icon) {
  return mk("div", "sep", svg(icon || "info") + "<span></span>").appendChild(
    document.createTextNode(name)
  ).parentNode;
}

/* The standard layout of a settings popup: who it is at the top (Name and Icon, side by side), then one block per topic under its own heading, then where it sits, then the actions at the bottom (a pair per row, dangerous ones in red), then what it is. stgIdentity and stgActions build the first and the last blocks. */
function stgIdentity(parent, nameRow, iconRow, third) {
  var grid = mk("div", "ap-grid");
  grid.appendChild(nameRow);
  grid.appendChild(iconRow);
  if (third) grid.appendChild(third);
  parent.appendChild(grid);
  return grid;
}

/* `rows` are pills; the ones in `danger` are drawn in red. */
function stgActions(parent, rows, danger) {
  var grid = mk("div", "ap-grid");
  rows.forEach(function (r) {
    if (danger && danger.indexOf(r) >= 0) r.classList.add("danger");
    grid.appendChild(r);
  });
  parent.appendChild(grid);
  return grid;
}

function glance(items, cols) {
  var g = mk("div", "glance");
  g.style.gridTemplateColumns = "repeat(" + cols + ",1fr)";
  items.forEach(function (it) {
    var b = mk("div", "gb pane", "<b>-</b><span></span>");
    b.querySelector("span").textContent = it[0];
    var v = b.querySelector("b");
    b.refresh = function () {
      var x = it[1]();
      if (it[2]) b.querySelector("span").textContent = it[2]();
      v.textContent = x;
      b.classList.toggle("off", x.indexOf(_T("offline")) >= 0);
    };
    reg(b.refresh);
    g.appendChild(b);
  });
  return g;
}

function switchPill(icon, name, id) {
  return pill(icon, name, {
    on: function () {
      return isOn(id);
    },
    sub: function () {
      return stAgo(id);
    },
    tap: function () {
      toggleEnt(id);
    },
    pin: { id: id, name: name, icon: icon },
  });
}

function actionPill(icon, name, fn, confirmText) {
  return pill(icon, name, {
    tap: function () {
      if (confirmText) confirmDlg(confirmText, fn);
      else fn();
    },
  });
}

/* Files, for every export and import: one place that saves a text file on this device and one that asks for a file and reads it as text, so each can say what went wrong. */
function fileStamp() {
  var d = new Date(),
    p = function (n) {
      return ("0" + n).slice(-2);
    };
