/* Guided setup of a device: the other entities that belong to it (a TV's remote, a camera's second stream and its pan/tilt controls), found by themselves where Home Assistant says they belong together and chosen with a searchable list where it does not. What is linked is kept with the device (`links`) and is what the Advanced settings of that device list. */

/* A kind of device that has other entities, and what each of them is for. `domains` are the entity types that fit, `re` narrows them by name, `many` allows more than one, `auto` lets "find automatically" link every one that is near. */
var DEVSETUP = {
  ac: {
    label: "ac",
    slots: [
      { key: "climate", domains: ["climate"], many: 1, auto: 1, hint: "ac_climate_hint" },
      { key: "controls", domains: ["switch", "select", "number", "button", "input_boolean", "input_select", "input_number", "script"], re: /swing|fan|display|light|sleep|quiet|eco|turbo|clean|beep|health|ion|purif|self|timer|mode|power|temperature|apply/i, many: 1, hint: "ac_controls_hint" },
      { key: "readings", domains: ["sensor", "binary_sensor"], re: /temperature|humidity|power|energy|filter|outdoor|indoor|error|defrost/i, many: 1, hint: "ac_readings_hint" },
    ],
  },
  vacuum: {
    label: "vacuum",
    slots: [
      { key: "rooms", domains: ["button", "select", "switch"], re: /room|zone|segment|area|map|clean|spot|dock|empty|wash|dry/i, many: 1, hint: "vacuum_rooms_hint" },
      { key: "care", domains: ["sensor", "binary_sensor"], re: /filter|brush|mop|cloth|bin|tank|dust|water|consumable|sensor_dirty|cleaning_time|cleaned_area|error|battery/i, many: 1, hint: "vacuum_care_hint" },
      { key: "options", domains: ["switch", "select", "number"], re: /dnd|volume|carpet|child|mop|water|suction|mode|speed|voice|led|resume|boost/i, many: 1, hint: "vacuum_options_hint" },
    ],
  },
  receiver: {
    label: "receiver",
    slots: [
      { key: "remote", domains: ["remote"], hint: "tv_remote_hint" },
      { key: "sound", domains: ["select", "switch", "number"], re: /sound|mode|zone|input|eq|bass|treble|dialog|night|dynamic|surround|pure|bypass|subwoofer/i, many: 1, hint: "receiver_sound_hint" },
    ],
  },
  purifier: {
    label: "purifier",
    slots: [
      { key: "air", domains: ["sensor"], re: /pm|aqi|air|filter|humidity|temperature|voc|co2|odor|dust/i, many: 1, hint: "purifier_air_hint" },
      { key: "options", domains: ["switch", "select", "number", "button"], re: /led|buzzer|child|auto|favorite|mode|level|display|alarm|reset/i, many: 1, hint: "purifier_options_hint" },
    ],
  },
  tv: {
    label: "tv",
    slots: [
      { key: "remote", domains: ["remote"], hint: "tv_remote_hint" },
      { key: "extras", domains: ["select", "switch", "button"], re: /app|source|input|picture|sound|game|ambient|mute|menu|home|back/i, many: 1, hint: "tv_extras_hint" },
    ],
  },
  camera: {
    label: "camera",
    slots: [
      { key: "stream", domains: ["camera"], hint: "camera_stream_hint" },
      { key: "ptz", domains: ["button", "select", "number", "cover"], re: /ptz|\bpan\b|tilt|zoom|preset|patrol|cruise|move[_ ](up|down|left|right)|\b(up|down|left|right)\b|calibrat/i, many: 1, hint: "camera_ptz_hint" },
      { key: "privacy", domains: ["switch"], re: /privacy|lens[_ ]mask|shutter|\bsleep\b|\bcover(ed)?\b/i, hint: "camera_privacy_hint" },
      { key: "motion", domains: ["binary_sensor"], re: /motion|person|human|\bpet\b|vehicle|animal|baby|cry|detect|alarm|tamper/i, many: 1, hint: "camera_motion_hint" },
    ],
  },
};

/* The setup a device has, or null (a plain device has none). */
function devSetupKind(d) {
  if (!d || !d.id) return null;
  if (d.kind === "camera") return "camera";
  if (d.kind === "climate") return "ac";
  if (d.kind === "vacuum") return "vacuum";
  var t = d.dt || guessDevType(d);
  if (d.kind === "fan") return t === "purifier" ? "purifier" : null;
  if (d.kind === "media") return t === "tv" ? "tv" : t === "receiver" ? "receiver" : null;
  return null;
}

/* Whether adding a device of this kind should open its setup page straight away: a TV and a camera always (they need their remote and stream), the others only when something belongs to them. */
function devSetupAlways(kind) {
  return kind === "tv" || kind === "camera";
}

function kName(eid) {
  return A(eid).friendly_name || eid;
}

/* Entities Home Assistant says belong with this one: on the same device, or (when it has no device) named like it in the same area. */
function kNear(id) {
  var h = H(),
    e = h.entities && h.entities[id];
  if (!e) return [];
  var base = String(A(id).friendly_name || id).toLowerCase().split(/[\s_]+/)[0];
  return Object.keys(h.entities).filter(function (k) {
    var x = h.entities[k];
    if (k === id || !h.states[k] || x.disabled_by || x.hidden) return false;
    if (e.device_id) return x.device_id === e.device_id;
    return base.length >= 3 && areaIdOf(k) === areaIdOf(id) && kName(k).toLowerCase().indexOf(base) === 0;
  });
}

function kFits(slot, eid) {
  return slot.domains.indexOf(dom(eid)) >= 0 && (!slot.re || slot.re.test(eid + " " + kName(eid)));
}

/* Which slot an entity linked to the device is for. */
function kSlotOf(kind, eid) {
  var slots = DEVSETUP[kind].slots;
  for (var i = 0; i < slots.length; i++) if (kFits(slots[i], eid)) return slots[i];
  return null;
}

function kLinked(d, slot) {
  return (d.links || []).filter(function (eid) {
    return kSlotOf(devSetupKind(d), eid) === slot;
  });
}

function kLink(d, slot, eid) {
  d.links = (d.links || []).filter(function (x) {
    return x !== eid && (slot.many || kSlotOf(devSetupKind(d), x) !== slot);
  });
  d.links.push(eid);
  d.links = d.links.slice(-12);
}

function kUnlink(d, eid) {
  d.links = (d.links || []).filter(function (x) {
    return x !== eid;
  });
  if (!d.links.length) delete d.links;
}

/* Links what is found for every slot that has nothing yet. Returns how many were added. */
function kAuto(d) {
  var kind = devSetupKind(d);
  if (!kind) return 0;
  var near = kNear(d.id),
    n = 0;
  /* An air conditioner can come as more than one climate entity (an integration's and a helper's): those named after it belong with it. */
  if (kind === "ac")
    Object.keys(H().states).forEach(function (k) {
      if (dom(k) === "climate" && k !== d.id && k.indexOf(d.id) === 0 && near.indexOf(k) < 0) near.push(k);
    });
  DEVSETUP[kind].slots.forEach(function (slot) {
    if (kLinked(d, slot).length) return;
    near
      .filter(function (eid) {
        return kFits(slot, eid) && (slot.re || slot.auto || !slot.many);
      })
      .slice(0, slot.many ? 8 : 1)
      .forEach(function (eid) {
        kLink(d, slot, eid);
        n++;
      });
  });
  return n;
}

/* What a TV can be asked to do through its media player, and so whether the full remote can be shown or only the basic one. */
var KTV = [
  [1, "pause"],
  [4, "volume"],
  [8, "mute"],
  [128, "power_on"],
  [256, "power_off"],
  [512, "play_media"],
  [2048, "source"],
];

function kTier(d) {
  var feat = A(d.id).supported_features || 0,
    missing = KTV.filter(function (f) {
      return !(feat & f[0]);
    }).map(function (f) {
      return f[1];
    }),
    remote = d.links && d.links.some(function (e) {
      return dom(e) === "remote";
    }),
    e = H().entities[d.id],
    plat = e ? e.platform : "";
  /* some integrations offer little where another one for the same TV offers the apps, sources and keys */
  var better = Integrations.media.better(
    plat,
    Object.keys(H().entities).map(function (k) {
      return H().entities[k].platform;
    })
  );
  var full = missing.indexOf("source") < 0 && missing.indexOf("volume") < 0 && missing.indexOf("power_off") < 0;
  return { tier: full || remote ? "full" : "basic", missing: missing, remote: !!remote, suggest: better };
}

/* ---- the setup page of a device ---- */

function kwizPage(b, key) {
  var d = devAt(key),
    kind = devSetupKind(d);
