        W +
        " " +
        (Hh - PB) +
        "L" +
        bk[0][0].toFixed(1) +
        " " +
        (Hh - PB) +
        'Z" fill="url(#cg' +
        sid +
        ')" />';
    out +=
      '<path d="' +
