/* Adds a section of the chosen type to a page and returns it. A type that exists once per page keeps its own name as id. */
function secAdd(sc, k) {
  var arr = secOrder(sc),
    ty = SECTYPES[k];
  if (!ty) return null;
  if (
    ty.one &&
    arr.some(function (x) {
      return x.k === k;
    })
  ) {
    toast(_T("this_page_already_has_one"));
    return null;
  }
  var e = {
    id:
      ty.one &&
      !arr.some(function (x) {
        return x.id === k;
      })
        ? k
        : newSecId(arr),
    k: k,
    hide: false,
  };
  if (ty.own) e.devs = [];
  arr.push(e);
  setSecOrder(sc, arr);
  uiChanged();
  return e;
}

