    sp.parts.forEach(function (q) {
      q.vy += 520 * ds;
      q.x += q.vx * ds;
      q.y += q.vy * ds;
      g.beginPath();
      g.arc(q.x, q.y, 0.7, 0, 6.2832);
      g.fill();
    });
