  if (v && Array.isArray(v.temps))
    o.temps = v.temps
      .filter(function (k, i, a) {
        return typeof k === "number" && k >= 1000 && k <= 20000 && a.indexOf(k) === i;
      })
      .slice(0, 16)
      .map(Math.round);
  return o;
}

function cleanCfg(c) {
  var o = {
    rb: {},
