          if (!/^(\d{1,3}|[a-z0-9_]{1,40}:[A-Za-z0-9_-]{1,24})$/.test(id) || !p || typeof p !== "object") return;
          var q = {};
          ["mode", "fan", "water"].forEach(function (k) {
