/* The parts of a thing, drawn on the floor. */
function eaBuildDummy(m, i, parent) {
  var key = "d" + i,
    g = eaSvg("g", { class: "ae-th" }, parent),
    kind = EA_DUMMIES.filter(function (k) {
      return k[0] === m.k;
    })[0],
    parts = {
      left: eaSvg("polygon", { class: "ae-f1" }, g),
      right: eaSvg("polygon", { class: "ae-f2" }, g),
      top: eaSvg("polygon", { class: "ae-f3" }, g),
      label: eaSvg("text", { class: "ae-tx", "text-anchor": "middle" }, g),
    };
  parts.label.textContent = _T(kind ? kind[1] : "other");
  EAD.v.els[key] = parts;
  ["top", "left", "right"].forEach(function (p) {
    eaAttach(parts[p], key);
  });
  eaDrawDummy(key);
}

/* The parts of a light: shadow, pole, dot, and for a bar its zones and the handle at its end. */
function eaBuildLight(l, parent) {
  var g = eaSvg("g", {}, parent),
    parts = {
      shadow: eaSvg("ellipse", { class: "ae-sh", rx: 16, ry: 7 }, g),
      pole: eaSvg("line", { class: "ae-pole" }, g),
    },
    bar = eaIsBar(l.id),
    col = lightRgb(l.id);
  if (bar) {
    var zc = A(l.id).zone_colors || [];
    parts.bar = eaSvg("line", { class: "ae-bar" }, g);
    parts.zd = zoneMembers(l.id).map(function (m, i) {
      var c = eaSvg("circle", { class: "ae-zd", r: 9 }, g);
      if (V_(l.id) === "on" && zc[i]) c.style.fill = cssRgb(liveXyRgb(zc[i][0], zc[i][1]));
      return c;
    });
  }
  parts.dot = eaSvg("circle", { class: "ae-dot", r: 17 }, g);
  parts.hit = eaSvg("circle", { class: "ae-hit", r: 34 }, g);
  if (bar) {
    parts.end = eaSvg("circle", { class: "ae-end", r: 14 }, g);
    eaAttachEnd(parts.end, l.id);
  }
  if (col) parts.dot.style.fill = cssRgb(col);
  EAD.v.els[l.id] = parts;
  eaAttach(parts.hit, l.id);
  eaDrawLight(l.id);
}

/* Everything in the room is made again from the draft (lights drawn back to front, so one in front hides one behind it). Dragging only moves pieces, so a drag is never cut off by this. */
function eaBuild() {
  var v = EAD.v,
    d = EAD.draft;
  v.things.innerHTML = "";
  v.lightsG.innerHTML = "";
  v.els = {};
  d.dummies.forEach(function (m, i) {
    eaBuildDummy(m, i, v.things);
  });
  d.lights
    .slice()
    .sort(function (p, q) {
      return p.x + p.y - (q.x + q.y);
    })
    .forEach(function (l) {
      eaBuildLight(l, v.lightsG);
    });
  eaMark();
}

/* A drag across the floor in Location, up and down in Height. */
function eaDragLight(key, p, start) {
  var l = eaLightOf(key);
  if (EAD.v.mode === "h") {
    var zn = Math.max(0, Math.min(1, (l.z + 1) / 2 + (start[1] - p[1]) / EA_V.wall));
    l.z = eaRound(zn * 2 - 1);
  } else {
    var f = eaFloor(p[0], p[1], (l.z + 1) / 2);
    l.x = f[0];
    l.y = f[1];
  }
  eaDrawLight(key);
}

/* Dragging a light or a thing. */
function eaAttach(el, key) {
  var down = false,
    start = null,
    isLight = !eaIsDummy(key);
  el.style.touchAction = "none";
  el.addEventListener("pointerdown", function (e) {
    e.stopPropagation();
    down = true;
    start = eaPoint(e);
    dragging++;
    DRAGAT = Date.now();
    capturePointer(el, e);
    if (EAD.sel !== key) eaSelect(key);
  });
  el.addEventListener("pointermove", function (e) {
    if (!down) return;
    var p = eaPoint(e);
    if (isLight) {
      eaDragLight(key, p, start);
      if (EAD.v.mode === "h") start = p;
    } else {
      var m = eaDummyOf(key),
        g = eaFloor(p[0], p[1], 0);
      m.x = g[0];
      m.y = g[1];
      eaDrawDummy(key);
    }
  });
  function end() {
    if (!down) return;
    down = false;
    dragging = Math.max(0, dragging - 1);
    if (isLight && EAD.v.mode === "loc") eaBuild();
    eaMark();
    eaInfo();
  }
  el.addEventListener("pointerup", end);
  el.addEventListener("pointercancel", end);
}

/* The end of a bar: dragging it turns the bar and sets its length (Location), on the floor at the bar's height. */
function eaAttachEnd(el, key) {
  var down = false;
  el.style.touchAction = "none";
  el.addEventListener("pointerdown", function (e) {
    e.stopPropagation();
    down = true;
    dragging++;
    DRAGAT = Date.now();
    capturePointer(el, e);
    if (EAD.sel !== key) eaSelect(key);
  });
  el.addEventListener("pointermove", function (e) {
    if (!down) return;
    var l = eaLightOf(key),
      p = eaPoint(e),
      f = eaFloor(p[0], p[1], (l.z + 1) / 2),
      dx = f[0] - l.x,
      dy = f[1] - l.y,
      run = Math.hypot(dx, dy);
    if (run < 0.03) return;
    var pitch = ((l.p || 0) * Math.PI) / 180;
    l.a = Math.round(((Math.atan2(dy, dx) * 180) / Math.PI + 360) % 360);
    l.len = Math.round(Math.max(0.2, Math.min(2, (2 * run) / Math.max(0.2, Math.cos(pitch)))) * 100) / 100;
    eaDrawLight(key);
  });
  function end() {
    if (!down) return;
    down = false;
    dragging = Math.max(0, dragging - 1);
    eaInfo();
  }
  el.addEventListener("pointerup", end);
  el.addEventListener("pointercancel", end);
}

/* The lights of the room as cards, coloured like the lights: tap one to add it to the area or to pick it. */
function eaTray() {
  var v = EAD.v,
    d = EAD.draft;
  v.tray.innerHTML = "";
  Object.keys(v.byId).forEach(function (id) {
    var dev = v.byId[id],
      rgb = lightRgb(id),
      card = mk(
        "div",
        "ae-card" + (eaLightOf(id) ? " in" : "") + (EAD.sel === id ? " picked" : ""),
        svg(dev.icon || "light")
      );
    card.dataset.id = id;
    card.appendChild(mk("span", "ae-cn")).textContent = dev.name;
    if (rgb) {
      card.style.color = "#fff";
      card.style.background =
        "linear-gradient(160deg," +
        cssRgb(rgb) +
        "," +
        cssRgb(
          rgb.map(function (c) {
            return c * 0.55;
          })
        ) +
        ")";
    }
    card.addEventListener("click", function () {
      if (!eaLightOf(id)) {
        if (!eaAddLight(dev)) return;
        eaBuild();
        eaTray();
      }
      eaSelect(id);
    });
    v.tray.appendChild(card);
  });
}

/* Places a light of the tray (`dev`: {id, icon, bar}) in the area's draft, in the next free spot. False, with a message, when the area is full. */
function eaAddLight(dev) {
  var d = EAD.draft;
  if (d.lights.length >= 32) {
    toast(_T("up_to_32_lights_in_an_area"));
    return false;
  }
  var slot = EA_SLOTS[d.lights.length % EA_SLOTS.length],
    nl = { id: dev.id, x: slot[0], y: slot[1], z: eaStartHeight(dev.icon) };
  if (dev.bar) {
    nl.a = 0;
    nl.p = 0;
    nl.len = 0.6;
  }
  d.lights.push(nl);
  return true;
}

/* The lights that are not in the tray yet: any light of Home Assistant that can be placed, from any room or none, found the way the page's "add a device" finds them. A group is offered while any of its members is not in the tray. The sync switches of Hue (listed there as lights) are not lights and are left out. */
function eaOtherLights(q) {
  var byId = EAD.v.byId;
  return candidates(["light"], EAD.room, q).filter(function (c) {
    if (c.id.indexOf("light.") !== 0) return false;
    return eaUnits([c.id]).some(function (id) {
      return !byId[id];
    });
  });
}

/* The page behind "Add a light": each tap puts the light (or the members of a group) in the tray and in the area, and the list goes on without it. */
function eaMorePage(b) {
  var inp = mk("input", "sq"),
    w = mk("div", "sqw pane", svg("search")),
    box = mk("div"),
    q = "";
  inp.type = "text";
  inp.placeholder = _T("search_lights");
  inp.setAttribute("autocomplete", "off");
  inp.setAttribute("autocapitalize", "off");
  w.appendChild(inp);
  b.appendChild(w);
  b.appendChild(box);
  function list() {
    redrawBox(box, function () {
      var items = eaOtherLights(q),
        shown = items.slice(0, 40);
      if (!items.length)
        box.appendChild(
          pill("info", _T("nothing_to_add_here"), {
            sub: function () {
              return _T("every_light_that_can_be_placed_is_in");
            },
          })
        );
      shown.forEach(function (c) {
        box.appendChild(
          pill(defIcon("light", c.name, c.id), c.name, {
            sub: function () {
              return (c.area ? c.area + " · " : "") + c.id;
            },
            tap: function () {
              var units = eaUnits([c.id]).filter(function (id) {
                return !EAD.v.byId[id];
              });
              var added = 0;
              for (var i = 0; i < units.length; i++) {
                var dev = { id: units[i], name: units.length > 1 ? entName(units[i]) : c.name, icon: "light", bar: eaIsBar(units[i]) };
                if (!eaAddLight(dev)) break;
                EAD.v.byId[dev.id] = dev;
                added++;
              }
              if (added) {
                eaBuild();
                eaTray();
                eaInfo();
                eaActions();
                toast(_T("added", { x: c.name }));
              }
              list();
            },
          })
        );
      });
      if (items.length > shown.length) {
        box.appendChild(hintRow(_T("more_type_to_narrow_the_list", { x: items.length - shown.length })));
      }
    });
  }
  inp.addEventListener("input", function () {
    q = inp.value;
    list();
  });
  list();
}

/* Things in the room (a TV, a speaker, ...) are added from their own row of cards; each can be added more than once, dragged anywhere on the floor and resized. */
function eaThings(b) {
  var d = EAD.draft,
    row = mk("div", "ae-tray ae-things");
  b.appendChild(sep(_T("things_in_the_room"), "home"));
  b.appendChild(row);
  EA_DUMMIES.forEach(function (k) {
    var card = mk("div", "ae-card thing in", svg(k[2]));
    card.appendChild(mk("span", "ae-cn")).textContent = _T(k[1]);
    card.addEventListener("click", function () {
      if (d.dummies.length >= 16) {
        toast(_T("up_to_16_things"));
        return;
      }
      /* Each new thing goes to a free place along the front, so none hides another. */
      var n = d.dummies.length;
      d.dummies.push({
        k: k[0],
        x: eaRound(-0.7 + 0.35 * (n % 5)),
        y: eaRound(0.75 - 0.35 * Math.floor(n / 5)),
        w: 0.5,
        h: 0.3,
      });
      eaBuild();
      eaSelect("d" + (d.dummies.length - 1));
    });
    row.appendChild(card);
  });
}

/* A slider for one number of the picked piece: f has field, label, min, max, step, def (shown when unset), fmt, round and after (what to redraw). */
function eaSlider(o, f) {
  return sliderRow({
    icon: "axis",
    name: _T(f.label),
    min: f.min,
    max: f.max,
    step: f.step,
    get: function () {
      return o[f.field] === undefined ? f.def : o[f.field];
    },
    fmt: f.fmt,
    commit: function (v) {
      o[f.field] = f.round(v);
      f.after();
    },
  });
}

function eaDeg(v) {
  return Math.round(v) + "°";
}

function eaPercent(v) {
  return Math.round(v * 50) + "%";
}

/* What can be set for the picked light: its height, and for a bar its direction, tilt and length. */
function eaLightInfo(info, lm) {
  var dev = EAD.v.byId[lm.id],
    redraw = function () {
      eaDrawLight(lm.id);
    },
    rows = [
      {
        field: "z",
        label: "height",
        min: -1,
        max: 1,
        step: 0.1,
        def: 0,
        round: eaRound,
        fmt: function (v) {
          return v <= -0.7 ? _T("floor") : v >= 0.7 ? _T("ceiling") : Math.round(((v + 1) / 2) * 100) + "%";
        },
      },
    ];
  /* An area a plugin owns can have settings of each light that this editor does not know (Hue's brightness balance): the plugin's rows. */
  if (EAD.external && pluginAreaOwner().lightRows)
    pluginAreaOwner()
      .lightRows()
      .forEach(function (r) {
        rows.push(r);
      });
  if (eaIsBar(lm.id))
    rows.push(
      { field: "a", label: "direction", min: 0, max: 355, step: 5, def: 0, round: Math.round, fmt: eaDeg },
      { field: "p", label: "tilt", min: 0, max: 90, step: 5, def: 0, round: Math.round, fmt: eaDeg },
      {
        field: "len",
        label: "length",
        min: 0.2,
        max: 2,
        step: 0.1,
        def: 0.6,
        round: function (v) {
          return Math.round(v * 100) / 100;
        },
        fmt: eaPercent,
      }
    );
  info.appendChild(sep(dev ? dev.name : entName(lm.id), dev ? dev.icon : "light"));
  if (eaIsBar(lm.id)) eaOrientRows(info, lm);
  rows.forEach(function (f) {
    f.after = redraw;
    info.appendChild(eaSlider(lm, f));
  });
  info.appendChild(
    pill("trash", _T("remove_from_this_area"), {
      tap: function () {
        EAD.draft.lights = EAD.draft.lights.filter(function (l) {
          return l !== lm;
        });
        eaSelect(null);
        eaBuild();
        eaTray();
      },
    })
  );
}

/* How a bar stands, as three choices (the Hue app's "Orientation setup"): lying flat or standing up, parallel or perpendicular to the wall the speakers stand at (the back wall), its first
 zone (the cord) at the left or the right. They set its direction (a) and tilt (p); the sliders below fine-tune them. */
function eaOrientOf(l) {
  var a = ((((l.a || 0) % 360) + 360) % 360) * (Math.PI / 180),
    across = Math.abs(Math.sin(a)) > Math.abs(Math.cos(a));
  return { up: Math.abs(l.p || 0) >= 45, across: across, right: across ? Math.sin(a) < 0 : Math.cos(a) < 0 };
}

function eaOrientSet(l, o) {
  l.p = o.up ? 90 : 0;
  l.a = o.across ? (o.right ? 270 : 90) : o.right ? 180 : 0;
}

function eaOrientRows(info, lm) {
  [
    ["up", "lying_flat", "standing_up"],
    ["across", "parallel", "perpendicular"],
    ["right", "cord_at_left", "cord_at_right"],
  ].forEach(function (c) {
    info.appendChild(
      seg(
        [
          [false, _T(c[1])],
          [true, _T(c[2])],
        ],
        eaOrientOf(lm)[c[0]],
        function (v) {
          var o = eaOrientOf(lm);
          o[c[0]] = v;
          eaOrientSet(lm, o);
          eaDrawLight(lm.id);
          eaInfo();
        }
      )
    );
  });
}

/* What can be set for the picked thing: its width and depth. */
function eaDummyInfo(info, key, dm) {
  var kind = EA_DUMMIES.filter(function (k) {
    return k[0] === dm.k;
  })[0];
  info.appendChild(sep(_T(kind ? kind[1] : "other"), kind ? kind[2] : "plug"));
  [
    ["w", "width"],
    ["h", "depth"],
  ].forEach(function (f) {
    info.appendChild(
      eaSlider(dm, {
        field: f[0],
        label: f[1],
        min: 0.1,
        max: 2,
        step: 0.05,
        def: 0.4,
        round: eaRound,
        fmt: eaPercent,
        after: function () {
          eaDrawDummy(key);
        },
      })
    );
  });
  info.appendChild(
    pill("trash", _T("remove_from_the_room"), {
      tap: function () {
        EAD.draft.dummies.splice(Number(key.slice(1)), 1);
        eaSelect(null);
        eaBuild();
      },
    })
  );
}

/* The settings of the picked piece, under the room. */
function eaInfo() {
  var info = EAD.v.info;
  redrawBox(info, function () {
    var key = EAD.sel,
      lm = key && !eaIsDummy(key) ? eaLightOf(key) : null,
      dm = eaIsDummy(key) ? eaDummyOf(key) : null;
    if (lm) eaLightInfo(info, lm);
    else if (dm) eaDummyInfo(info, key, dm);
    else info.appendChild(pill("info", _T("tap_a_light_to_find_it_in_the_room"), {}));
  });
}

function eaActions() {
  var box = EAD.v.box;
  redrawBox(box, function () {
    if (EAD.external) return;
    pluginAreaEach("actions", box, EAD.draft);
    if (!EAD.isNew)
      box.appendChild(
        pill("trash", _T("delete_area"), {
          tap: function () {
            confirmDlg(_T("delete_named_q", { x: EAD.draft.name }), eaDelete, _T("delete_word"));
          },
        })
      );
  });
}

/* The Location | Height switch and the line that says what a drag does. */
function eaModeSwitch(b) {
  var hint = mk("div", "hint");
  hint.textContent = _T("drag_a_light_across_the_floor");
  b.appendChild(
    seg(
      [
        ["loc", _T("location")],
        ["h", _T("height")],
      ],
      EAD.v.mode,
      function (m) {
        EAD.v.mode = m;
        b.querySelectorAll(".seg .rbtn").forEach(function (r, i) {
          r.classList.toggle("act", i === (m === "loc" ? 0 : 1));
        });
        hint.textContent = m === "loc" ? _T("drag_a_light_across_the_floor") : _T("drag_a_light_up_or_down");
      }
    )
  );
  b.appendChild(hint);
}

function eaDirty() {
  return JSON.stringify(EAD.draft) !== EAD.saved;
}

function eaEditor(b) {
  if (EAD.saved === undefined) EAD.saved = JSON.stringify(EAD.draft);
  guardUnsaved({ dirty: eaDirty, save: eaSave, discard: eaIdentifyOff });
  var d = EAD.draft,
    w = mk("div", "sqw pane", svg("target")),
    inp = mk("input", "sq"),
    byId = {};
  inp.type = "text";
  inp.maxLength = 40;
  inp.placeholder = _T("area_name");
  inp.value = d.name;
  inp.addEventListener("input", function () {
    d.name = inp.value;
  });
  w.appendChild(inp);
  b.appendChild(w);
  if (EAD.external && EAD.external.note) b.appendChild(pill("info", EAD.external.note, {}));
  (EAD.external ? pluginAreaOwner().lights() : eaRoomLights(EAD.room)).forEach(function (l) {
    byId[l.id] = l;
  });
  d.lights.forEach(function (l) {
    if (!byId[l.id]) byId[l.id] = { id: l.id, name: entName(l.id), icon: "light" };
  });
  var cv = mk("div", "ae-c"),
    root = eaRoom();
  EAD.v = {
    mode: "loc",
    byId: byId,
    els: {},
    root: root,
    things: eaSvg("g", {}, root),
    lightsG: eaSvg("g", {}, root),
    tray: mk("div", "ae-tray"),
    info: mk("div"),
    box: mk("div"),
  };
  eaModeSwitch(b);
  cv.appendChild(root);
  b.appendChild(cv);
  root.addEventListener("pointerdown", function () {
    if (EAD.sel) eaSelect(null);
  });
  b.appendChild(EAD.v.tray);
  if (!EAD.external)
    b.appendChild(
      pill("plus", _T("add_a_light"), {
        sub: function () {
          return _T("any_light_of_home_assistant_from_any_");
        },
        tap: function () {
          showPopup("area-lights", true);
        },
      })
    );
  if (!EAD.external) eaThings(b);
  b.appendChild(EAD.v.info);
  b.appendChild(EAD.v.box);
  eaBuild();
  eaTray();
  eaInfo();
  eaActions();
  /* The light is put back when this screen goes away. */
  clearInterval(EA_KEEP.watch);
  EA_KEEP.watch = setInterval(function () {
    if (!cv.isConnected) {
      clearInterval(EA_KEEP.watch);
      eaIdentifyOff();
    }
  }, 1000);
}

/* Saves the area and goes on to `leave`. An area that cannot be saved says why and stays open (false); one a plugin owns answers later (a promise). */
function eaSave(leave) {
  if (EAD.external) return pluginAreaOwner().save(leave);
  var d = EAD.draft,
    name = String(d.name || "").trim();
  if (!name) {
    toast(_T("give_the_area_a_name"));
    return false;
  }
  if (!d.lights.length) {
    toast(_T("add_at_least_one_light"));
    return false;
  }
  var a = cleanArea({
    id: d.id || "a" + Date.now().toString(36),
    name: name,
    room: EAD.room,
    lights: d.lights,
    dummies: d.dummies,
  });
  if (!a) {
    toast(_T("couldn_t_save_this_area"));
    return false;
  }
  eaIdentifyOff();
  STORE.eareas = STORE.eareas.filter(function (x) {
    return x.id !== a.id;
  });
  STORE.eareas.push(a);
  uiChanged();
  livePush(liveScenesIn(a.id), [a]);
  toast(_T("area_saved"));
  EAD.saved = JSON.stringify(EAD.draft);
  POPGUARD = null;
  leave();
  return true;
}

function eaDelete() {
  var id = EAD.draft.id,
    used = STORE.scenes.filter(function (s) {
      return s.live && (s.live.areas && s.live.areas.length ? s.live.areas : [s.live.area]).indexOf(id) >= 0;
    }),
    shown = used.filter(function (s) {
      return sceneShown(s.id);
    });
  if (shown.length) {
    toast(
      _T("scenes_use_this_area") +
        shown
          .map(function (s) {
            return s.name;
          })
          .join(", ")
    );
    return;
  }
  if (used.length) {
    confirmDlg(
      _T("scenes_on_no_page_use_this_area") +
        used
          .map(function (s) {
            return s.name;
          })
          .join(", ") +
        _T("delete_them_with_the_area"),
      function () {
        used.forEach(function (s) {
          if (liveRun({ id: s.id })) liveCall("stop", { scene_id: s.id });
          liveForget(s.id, s.live.areas ? s.live.area : null);
        });
        STORE.scenes = STORE.scenes.filter(function (x) {
          return used.indexOf(x) < 0;
        });
        pruneSceneRefs();
        eaRemove(id);
      }
    );
    return;
  }
  eaRemove(id);
}

function eaRemove(id) {
  eaIdentifyOff();
  STORE.eareas = STORE.eareas.filter(function (x) {
    return x.id !== id;
  });
  uiChanged();
  liveForget(null, id);
  toast(_T("area_deleted"));
  POPGUARD = null;
  if (STACK.length) popBack();
  else closeSheet();
}

/* Wall mode: the idle clock or photo screensaver, and wall photos. */

/* The photos the wall screen shows: the gallery's photos that are switched on. */
function wallActive() {
  var c = STORE.cfg || {},
    off = c.wallOff || [];
  return (c.wallPhotos || []).filter(function (u, i) {
    return off.indexOf(i) < 0;
  });
}

/* The gallery of the wall screen's photos: each photo is a tile with a check that says whether it is used; a photo can be kept in the gallery without being used. New photos are
   uploaded from this device (or added by address) and are used at once. */
function wallPhotosPage(b) {
  var box = mk("div");
  b.appendChild(box);
  function photos() {
    return ((STORE.cfg && STORE.cfg.wallPhotos) || []).slice();
  }
  function off() {
    return ((STORE.cfg && STORE.cfg.wallOff) || []).slice();
  }
  function setAll(list, offList) {
    STORE.cfg = cleanCfg(Object.assign({}, STORE.cfg, { wallPhotos: list, wallOff: offList }));
    storeChanged();
    redrawBox(box, draw);
  }
  function toggle(i) {
    var o = off(),
      at = o.indexOf(i);
    if (at >= 0) o.splice(at, 1);
    else o.push(i);
    setAll(photos(), o);
  }
  function remove(i) {
    var list = photos(),
      o = off()
        .filter(function (x) {
          return x !== i;
        })
        .map(function (x) {
          return x > i ? x - 1 : x;
        });
    list.splice(i, 1);
    setAll(list, o);
  }
  function add(u) {
    if (photos().length >= 16) {
      toast(_T("up_to_16_photos"));
      return;
    }
    setAll(photos().concat([u]), off());
  }
  function tile(u, i) {
    var used = off().indexOf(i) < 0,
      t = mk("div", "wg-t pane" + (used ? " on" : " off")),
      img = mk("img"),
      ck = mk("span", "wg-ck", svg("check")),
      x = mk("div", "rnd pane sm wg-x", svg("trash"));
    img.alt = "";
    img.draggable = false;
    img.src = u;
    t.setAttribute("role", "checkbox");
    t.setAttribute("aria-checked", used ? "true" : "false");
    t.setAttribute("aria-label", _T("photo_n", { x: (i + 1) }));
    t.tabIndex = 0;
    t.appendChild(img);
