                : _T("loading");
            },
            val: function () {
              var s = V_(id);
              return isNaN(parseFloat(s))
                ? ""
                : parseFloat(s).toFixed(1) + " " + (A(id).unit_of_measurement || "");
            },
          });
        })
      ),
      wide: false,
    });
  if (E.power.length)
    list.push({
      el: section(
        _T("power"),
        "plug",
        E.power.map(function (id) {
          return pill("plug", entName(id), {
