              var s = V_(id);
              return isNaN(parseFloat(s))
                ? ""
                : Math.round(parseFloat(s) * 10) / 10 + " " + (A(id).unit_of_measurement || "");
            },
          });
        })
      ),
      wide: false,
    });
  return list;
}

