/* The people who can be chosen: every active person of Home Assistant. Only an admin can list them; the names are kept for the summaries. */
var RULE_USERS = null;

function ruleUsers(cb) {
  if (RULE_USERS) return cb(RULE_USERS);
  HA.users()
    .then(function (l) {
      RULE_USERS = l
        .filter(function (u) {
          return !u.system_generated && u.is_active;
        })
        .map(function (u) {
          return { id: u.id, name: u.name };
        });
      cb(RULE_USERS);
    })
    .catch(function () {
      cb([]);
    });
}

function ruleUserName(id) {
  var u = (RULE_USERS || []).filter(function (x) {
    return x.id === id;
  })[0];
  return u ? u.name : _T("user");
}

function withAttr(out, c) {
  if (typeof c.attr === "string" && RE_ATTR.test(c.attr)) out.attr = c.attr;
  return out;
}

/* What a condition reads: the entity's state, or the attribute it names (undefined when it has none). */
function condValue(c) {
  if (!c.attr) return V_(c.id);
  var v = A(c.id)[c.attr];
  return v === undefined || v === null ? undefined : String(v);
}

/* Every kind of entity there is, for choosing what a condition reads. */
function allDomains() {
  return Object.keys(H().states)
    .map(dom)
    .filter(function (d, i, all) {
      return all.indexOf(d) === i;
    });
}

/* "State", or one of the entity's attributes. */
function attrPick(box, c, redraw) {
  var names = Object.keys(A(c.id)).filter(function (k) {
    return RE_ATTR.test(k) && ["friendly_name", "icon", "entity_picture", "supported_features"].indexOf(k) < 0;
  });
  if (!names.length && !c.attr) return;
  box.appendChild(
    dropRow(
      _T("cond_reads"),
      [""].concat(names),
      function () {
        return c.attr || "";
      },
      function (v) {
        if (v) c.attr = v;
        else delete c.attr;
        if (c.c === "state") c.is = String(condValue(c) === undefined ? "on" : condValue(c)).slice(0, 40);
        redraw();
      },
      "info",
      function (v) {
        return v || _T("state");
      }
    )
  );
}

function cleanCond(c) {
  if (!c) return null;
  if (c.c === "days") {
    var d = Array.isArray(c.days) && c.days.length === 7 ? c.days.map(Boolean) : null;
    return d && d.some(Boolean) && !d.every(Boolean) ? { c: "days", days: d } : null;
  }
  if (c.c === "between")
    return HHMM.test(c.from) && HHMM.test(c.to) && c.from !== c.to
      ? { c: "between", from: c.from, to: c.to }
      : null;
  if (c.c === "home")
    return c.v === "someone" || c.v === "nobody" || RE_WHO.test(c.v) ? { c: "home", v: c.v } : null;
  if (c.c === "users") {
    var ids = (Array.isArray(c.ids) ? c.ids : []).filter(function (x, i, a) {
      return typeof x === "string" && /^[a-f0-9]{32}$/.test(x) && a.indexOf(x) === i;
    });
    /* Nobody chosen yet is kept: it means everyone, and keeps the condition being edited from vanishing. */
    return { c: "users", ids: ids.slice(0, 40) };
  }
  if (c.c === "sun") return c.v === "dark" || c.v === "light" ? { c: "sun", v: c.v } : null;
  if (c.c === "sunrise")
    return (c.op === "after" || c.op === "before") && HHMM.test(c.at)
      ? { c: "sunrise", op: c.op, at: c.at }
      : null;
  if (c.c === "state") {
    var is = typeof c.is === "string" ? c.is.trim() : "";
    return RE_STATE.test(c.id) && RE_SVAL.test(is) ? withAttr({ c: "state", id: c.id, is: is }, c) : null;
  }
  if (c.c === "sensor") {
    var v = numIn(c.val, -1e6, 1e6);
    if (!(RE_STATE.test(c.id) && v !== null)) return null;
    if (c.op === "above" || c.op === "below") return withAttr({ c: "sensor", id: c.id, op: c.op, val: v }, c);
    if (c.op === "between") {
      var v2 = numIn(c.val2, -1e6, 1e6);
      return v2 !== null && v2 > v
        ? withAttr({ c: "sensor", id: c.id, op: "between", val: v, val2: v2 }, c)
        : null;
    }
    return null;
  }
  return null;
}

