  function set(v) {
    if (c.c === v) return;
    Object.keys(c).forEach(function (k) {
      delete c[k];
    });
    c.c = v;
    if (v === "days") c.days = [true, true, true, true, true, false, false];
    if (v === "between") {
      c.from = "22:00";
      c.to = "07:00";
    }
    if (v === "users") c.ids = [];
    if (v === "home") c.v = "someone";
    if (v === "sun") c.v = "dark";
    if (v === "sunrise") {
      c.op = "after";
      c.at = "06:30";
    }
    if (v === "state") c.is = "on";
    if (v === "sensor") c.op = "above";
