        c.c,
        set
      )
    );
    box.appendChild(
      seg(
        [
          ["sun", _T("dark_or_light")],
          ["sunrise", _T("sunrise_time")],
          ["users", _T("who_sees_it")],
        ],
        c.c,
        set
      )
    );
    box.appendChild(
      seg(
        [
          ["state", _T("device_is")],
          ["sensor", _T("sensor_value")],
