      return x.getFullYear() + "-" + x.getMonth() + "-" + x.getDate();
    };
  if (k(d) === k(n)) return _T("today");
  if (k(d) === k(y)) return _T("yesterday");
  return d.toLocaleDateString(LOC(), { weekday: "long", day: "numeric", month: "long" });
}

function histTime(ts) {
