var NOTIFYKINDS = [
  "light",
  "media",
  "climate",
  "fan",
  "switch",
  "vacuum",
  "camera",
  "cover",
  "lock",
];

function offlineAll() {
  return devsOf()
    .filter(function (d) {
      return d.id && NOTIFYKINDS.indexOf(d.kind) >= 0;
    })
    .map(function (d) {
      return d.id;
    })
    .filter(function (id, i, a) {
      return a.indexOf(id) === i;
    });
}

function offlineList(r) {
  return r.scope === "all" ? offlineAll() : r.scope === "custom" ? r.ents : offlineDefault();
}

function offlineDefault() {
  return devsOf()
    .filter(function (d) {
      return d.id && ["camera", "climate", "vacuum"].indexOf(d.kind) >= 0;
    })
    .map(function (d) {
      return d.id;
    });
}

/* The name of the device behind the entity that triggered, as the dashboard names it: "Area · Device" (the entity's own name when it has no device). */
var NOTIFY_NAME =
  "{% set e = trigger.entity_id %}{% set a = area_name(e) %}{% set d = device_attr(e, 'name_by_user') or device_attr(e, 'name') or trigger.to_state.attributes.friendly_name %}{{ (a ~ ' · ' ~ d) if a else d }}";

/* The connectivity sensors that say a sleepy device still answers (which integrations: integrations.js). */
function remoteSensors() {
  var h = H();
  return Object.keys(h.states || {})
    .filter(function (id) {
      var e = h.entities && h.entities[id];
      return dom(id) === "binary_sensor" && e && Integrations.presence.platforms.indexOf(e.platform) >= 0 && A(id).device_class === "connectivity";
    })
    .sort();
}

function notifyPayload(k) {
  var r = nrule(k),
    trigs = [],
    msg = "",
    ents;
  if (k === "batt") {
    /* A device with a percentage is watched by it, one with only a low flag by the flag: never both, so one battery is one message. */
    var index = batIndex(),
      pct = [],
      flags = [];
    (r.scope === "custom" ? r.devs : UI.bats).forEach(function (d) {
      var p = index[d];
      if (!p) return;
      if (p.pct) pct.push(p.pct);
      else if (p.flag) flags.push(p.flag);
    });
    if (pct.length) trigs.push({ trigger: "numeric_state", entity_id: pct, below: r.thr });
    if (flags.length) trigs.push({ trigger: "state", entity_id: flags, to: "on" });
    msg = _T("nt_msg_battery", {
      name: NOTIFY_NAME,
      level: "{{ " + JSON.stringify(_T("nt_word_low")) + " if trigger.to_state.domain == 'binary_sensor' else " + JSON.stringify(_T("nt_word_at")) + " ~ trigger.to_state.state ~ '%' }}",
    });
  } else if (k === "offline") {
    ents = offlineList(r);
    if (ents.length)
      trigs.push({
        trigger: "state",
        entity_id: ents,
        to: "unavailable",
        "for": { minutes: r.mins || 5 },
      });
    var remotes = r.remotes ? remoteSensors() : [];
    if (remotes.length)
      trigs.push({
        trigger: "state",
        entity_id: remotes,
        to: "off",
        "for": { minutes: r.remMins || 30 },
      });
    msg = _T("nt_msg_offline", { name: NOTIFY_NAME });
  } else {
    ents = vacuumList().map(function (d) {
      return d.id;
    });
    if (ents.length) trigs.push({ trigger: "state", entity_id: ents, to: "error" });
    msg = _T("nt_msg_problem", { name: "{{ trigger.to_state.attributes.friendly_name }}" });
  }
  if (!trigs.length || !r.targets.length) return null;
  return {
    id: "dashboard_n_" + k,
    alias: _T("dashboard_notify", { x: NRULES[k].title }),
    description: _T("managed_by_the_dashboard_app_setting_2"),
    mode: "queued",
    triggers: trigs,
    conditions: [],
    actions: r.targets.map(function (t) {
      return { action: "notify." + t, data: { title: _T("home"), message: msg } };
    }),
  };
}

function syncNotify(k) {
  var p = notifyPayload(k),
    r = nrule(k);
  if (r.on && p) return window.HA.automations.save(p.id, p);
  return window.HA.automations.remove("dashboard_n_" + k).catch(function () {});
}

/* The automations are built here, so they only changed when someone saved a rule. What a rule watches also changes when a
   device is added to the dashboard or a battery sensor is tracked. This brings each switched-on automation back to what its
   rule builds now. It reads the automation in Home Assistant first and writes only when it differs, so opening the dashboard
   on several screens does not rewrite it each time. */
function stableForm(x, key) {
  if (Array.isArray(x)) {
    var a = x.map(function (v) {
      return stableForm(v);
    });
    return key === "entity_id" ? a.sort() : a;
  }
  if (x && typeof x === "object") {
    var o = {};
    Object.keys(x)
      .sort()
      .forEach(function (k) {
        o[k] = stableForm(x[k], k);
      });
    return o;
  }
  return x;
}

function notifyWatch(p) {
  return JSON.stringify(stableForm({ triggers: p.triggers, actions: p.actions }));
}

var NRECON = 0;

function notifyReconcile() {
  if (!ISADMIN || !STORE_READY || !H() || OFFLINE) return;
  if (!dataIsReal()) {
    notifyReconcileSoon();
    return;
  }
  Object.keys(NRULES).forEach(function (k) {
    var p = nrule(k).on ? notifyPayload(k) : null;
    if (!p) return;
    window.HA.automations
      .get(p.id)
      .then(
        function (cur) {
          return notifyWatch(cur) === notifyWatch(p) ? null : window.HA.automations.save(p.id, p);
        },
        function (e) {
          /* Only an automation that is not there is made again; a failed read says nothing about it. */
          return e && e.status_code === 404 ? window.HA.automations.save(p.id, p) : null;
        }
      )
      .catch(function () {});
  });
  watchReconcile();
}

/* The alerts for any entity are brought to what they build now, the same way. */
function watchReconcile() {
  watchRules().forEach(function (w) {
    var p = w.on ? watchPayload(w) : null;
    if (!p) return;
    window.HA.automations
      .get(p.id)
      .then(
        function (cur) {
          return notifyWatch(cur) === notifyWatch(p) ? null : window.HA.automations.save(p.id, p);
        },
        function (e) {
          return e && e.status_code === 404 ? window.HA.automations.save(p.id, p) : null;
        }
      )
      .catch(function () {});
  });
}

function notifyReconcileSoon() {
  clearTimeout(NRECON);
  NRECON = setTimeout(notifyReconcile, 3000);
}

