    actions = [
      function () {
        return H().callService("vacuum", "start", { entity_id: vacuum });
      },
    ];
  return before.concat(actions).reduce(function (p, step, i) {
    return p.then(i ? vacapPause : null).then(step);
  }, Promise.resolve());
