    room = null;
  for (var i = 0; i < UI.rooms.length; i++) if (UI.rooms[i].id === at[0]) room = UI.rooms[i];
  if (!room || at.length < 2) return room;
  var sec = ((UI.layout.rooms || {})[room.id] || []).filter(function (x) {
